// change_serializer.sv - pays the change one bill per clock: a 3-unit bill when 3 is owed and one is available, otherwise 1-unit bills.
// Generated by scripts/emit_sv.py from scripts/fsms.py - do not edit by hand.
// Flip-flops: D, logic: minimal POS (exact two-level minimisation with don't-cares),
// next-state 3 two-input gates, outputs 7 two-input gates.
// State encoding:
//   r0     = 00
//   r1     = 01
//   r2     = 10
//   r3     = 11
// State = amount still owed. load = 1 loads `amount` (the change of this cycle's purchase or refund).
// bill_out: 00 none, 01 one-unit bill, 10 three-unit bill.

module change_serializer (
  input  logic       clk,
  input  logic       rst,
  input  logic       load,
  input  logic [1:0] amount,
  input  logic       have3,     // a 3-unit bill is in the till
  output logic [1:0] bill_out,
  output logic       busy,
  output logic [1:0] owed       // amount still to pay (the state)
);
  logic d1, d0, bo1, bo0;
  assign d1     = owed[1] & owed[0] & ~have3;  // 2 gates
  assign d0     = owed[1] & ~owed[0];  // 1 gates
  assign bo1    = owed[1] & owed[0] & have3;  // 2 gates
  assign bo0    = (owed[1] | owed[0]) & (~owed[1] | ~owed[0] | ~have3);  // 4 gates
  assign busy   = (owed[1] | owed[0]);  // 1 gates

  always_ff @(posedge clk)
    if (rst)       owed <= 2'b00;
    else if (load) owed <= amount;
    else           owed <= {d1, d0};

  assign bill_out = {bo1, bo0};
endmodule
